from lib import build
R=[]
R.append((7837338,
("Chile de frijoles variados","Un excelente chile vegetariano que funciona con las legumbres que tenga en la despensa.","4","398 g",
 ["1 cucharada de aceite de girasol","1 cebolla, finamente picada","1 diente de ajo, machacado","1 pimiento rojo, picado en trozos pequeños","1 pimiento verde, picado en trozos pequeños","1 chile rojo, sin semillas y finamente picado","2 latas de 400 g de legumbres mixtas, escurridas y enjuagadas","1 lata de 400 g de tomates picados","2 cucharadas de puré de tomate","50 g de elote (maíz) congelado (descongelado)","1 cucharadita de comino molido","1 cucharadita de orégano seco","pimienta negra recién molida","2 cucharadas de cilantro fresco, picado","200 g de arroz basmati blanco, cocido según las instrucciones del paquete"],
 ["Caliente el aceite de girasol en una olla mediana, agregue la cebolla, el ajo, los pimientos rojo y verde y el chile, y fría de 3 a 4 minutos hasta que empiecen a ablandarse.","Triture ligeramente la mitad de las legumbres con el dorso de un tenedor. Agréguelas a la olla junto con las legumbres restantes, los tomates picados, el puré de tomate, el elote, el comino, el orégano, la sal y la pimienta.","Lleve a ebullición, reduzca el fuego y cocine a fuego lento durante 10 minutos. Incorpore el cilantro y sirva con el arroz cocido."],
 ["Puede agregar más o menos chile, según qué tan picante (o no) le guste la comida.","¿Por qué no probar con lentejas rojas o verdes, frijoles rojos o garbanzos?","Instrucciones para congelar (sin el arroz): Se puede congelar una vez cocinado. Luego descongele en el refrigerador o en el microondas y recaliente hasta que esté bien caliente por completo.","@FV"],[]),
("تشيلي بالفاصولياء المشكّلة","وصفة تشيلي نباتية رائعة يمكن تحضيرها بأي بقوليات متوفرة في مخزن طعامك.","4","398 جم",
 ["1 ملعقة كبيرة من زيت عباد الشمس","1 حبة بصل، مفرومة ناعمًا","1 فص ثوم، مهروس","1 حبة فلفل رومي أحمر، مفرومة قطعًا صغيرة","1 حبة فلفل رومي أخضر، مفرومة قطعًا صغيرة","1 حبة فلفل حار أحمر، منزوعة البذور ومفرومة ناعمًا","2 علبة (400 جم لكل علبة) من البقوليات المشكّلة، مصفّاة ومغسولة","1 علبة (400 جم) من الطماطم المقطعة","2 ملعقة كبيرة من معجون الطماطم","50 جم من الذرة الحلوة المجمّدة (مذابة)","1 ملعقة صغيرة من الكمون المطحون","1 ملعقة صغيرة من الأوريجانو المجفف","فلفل أسود مطحون طازجًا","2 ملعقة كبيرة من الكزبرة الخضراء الطازجة، مفرومة","200 جم من أرز بسمتي أبيض، مطبوخ حسب التعليمات المدونة على العبوة"],
 ["سخّن زيت عباد الشمس في قدر متوسط، وأضف البصل والثوم والفلفل الرومي الأحمر والأخضر والفلفل الحار، وقلّبها لمدة 3-4 دقائق حتى تبدأ بالذبول.","اهرس نصف البقوليات هرسًا خفيفًا بظهر الشوكة. أضفها إلى القدر مع باقي البقوليات والطماطم المقطعة ومعجون الطماطم والذرة الحلوة والكمون والأوريجانو والملح والفلفل.","اتركها حتى تغلي، ثم خفّف الحرارة واتركها على نار هادئة لمدة 10 دقائق. حرّك الكزبرة الخضراء داخلها وقدّمها مع الأرز المطبوخ."],
 ["يمكنك إضافة كمية أكبر أو أقل من الفلفل الحار، بحسب مدى تفضيلك للطعام الحار.","لمَ لا تجرّب العدس الأحمر أو الأخضر أو الفاصولياء الحمراء أو الحمص.","تعليمات التجميد (دون الأرز): يمكن تجميدها بعد الطهي. ثم اتركها لتذوب في الثلاجة أو الميكروويف وأعد تسخينها حتى تصبح ساخنة تمامًا.","@FV"],[])))
R.append((7840147,
("Bacalao estofado con chícharos, cebollines y zanahorias","El bacalao en una salsa cremosa ligera es fácil de preparar y es una buena manera de aprovechar los chícharos congelados.","2","558 g",
 ["200 g de zanahorias baby Chantenay, cortadas por la mitad a lo largo","1 cubo de caldo de pescado bajo en sal","200 g de chícharos congelados","6 cebollines, cortados en rodajas de 2 cm","15 g de eneldo fresco","2 filetes gruesos de bacalao (unos 300 g)","1 cucharadita de maicena disuelta en 1 cucharada de agua","20 g de queso crema ligero","pimienta negra","2 rodajas de limón"],
 ["Precaliente el horno a 180 °C (marca de gas 4). Ponga las zanahorias en una cacerola con el cubo de caldo y 300 ml de agua. Lleve a ebullición, reduzca el fuego, tape y cocine a fuego lento durante 5 minutos.","Vierta las zanahorias y el caldo en una fuente para horno. Agregue los chícharos y los cebollines y esparza 10 g del eneldo.","Coloque los filetes de bacalao encima, cubra con papel aluminio y hornee durante 10 minutos.","Retire con cuidado el pescado y resérvelo. Agregue la maicena a las verduras, mezcle bien y regrese al horno durante un minuto.","Saque las verduras del horno e incorpore el queso crema. Divida las verduras y la salsa entre dos platos y coloque un trozo de bacalao encima de cada uno. Esparza el eneldo fresco y la pimienta negra, y sirva con limón."],
 ["Funciona bien con eglefino, salmón, rape o abadejo. Podría agregar algunos camarones.","Si no tiene chícharos congelados, los chícharos enlatados en agua o el elote congelado funcionan igual de bien con esta receta.","También puede cocinarlo en la estufa en una olla con tapa bien ajustada.","Para prepararlo con anticipación, cocine las zanahorias en el caldo y deje enfriar; arme todo en una fuente para horno y refrigere hasta que lo necesite. Calcule 5 minutos adicionales de cocción si lo cocina directamente desde el refrigerador.","@FV"],[]),
("سمك القد المطهو ببطء مع البازلاء والبصل الأخضر والجزر","سمك القد في صلصة كريمية خفيفة سهل التحضير، وهو طريقة جيدة لاستخدام البازلاء المجمّدة.","2","558 جم",
 ["200 جم من الجزر الصغير (شانتيناي)، مقطع إلى نصفين طوليًا","1 مكعب مرق سمك قليل الملح","200 جم من البازلاء المجمّدة","6 حبات بصل أخضر، مقطعة إلى شرائح بسمك 2 سم","15 جم من الشبت الطازج","2 شريحة سميكة من سمك القد (نحو 300 جم)","1 ملعقة صغيرة من نشا الذرة مذابة في 1 ملعقة كبيرة من الماء","20 جم من الجبن الكريمي الخفيف","فلفل أسود","2 شريحة ليمون"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4). ضع الجزر في قدر مع مكعب المرق و300 مل من الماء. اتركه حتى يغلي، ثم خفّف الحرارة وضع الغطاء واتركه على نار هادئة لمدة 5 دقائق.","اسكب الجزر والمرق في وعاء يصلح للفرن. أضف البازلاء والبصل الأخضر وانثر 10 جم من الشبت.","ضع شرائح سمك القد فوقها، وغطِّها بورق الألمنيوم واخبزها لمدة 10 دقائق.","أخرج السمك بحذر وضعه جانبًا. أضف نشا الذرة إلى الخضار، وقلّب جيدًا، وأعده إلى الفرن لمدة دقيقة واحدة.","أخرج الخضار من الفرن وقلّب فيها الجبن الكريمي. وزّع الخضار والصلصة على طبقين وضع قطعة سمك قد فوق كل طبق. انثر الشبت الطازج والفلفل الأسود وقدّمه مع الليمون."],
 ["تناسب هذه الوصفة سمك الحدوق أو السلمون أو سمك الضفدع البحري أو البولوك. ويمكنك إضافة بعض الجمبري.","إذا لم تتوفر لديك بازلاء مجمّدة، فإن البازلاء المعلبة في الماء أو الذرة الحلوة المجمّدة تناسب هذه الوصفة تمامًا.","يمكنك أيضًا طهيها على الموقد في قدر بغطاء محكم الإغلاق.","للتحضير المسبق، اطهِ الجزر في المرق ثم اتركه ليبرد، وجمّع كل شيء في وعاء يصلح للفرن ثم ضعه في الثلاجة حتى تحتاج إليه. أضف 5 دقائق إضافية لوقت الطهي إذا طهوته مباشرة من الثلاجة.","@FV"],[])))
R.append((7842764,
("Galletas de Pascua","Asociadas a menudo con el oeste de Inglaterra (West Country), estas galletas se comían tradicionalmente el Domingo de Pascua.","25","19 g",
 ["6 cucharadas de aceite de canola","1 huevo","50 g de azúcar morena suave (10 cucharaditas colmadas)","1.5 a 2 cucharaditas de stevia u otro endulzante (equivalente a 5 cucharaditas colmadas de azúcar)","ralladura fina de 1 limón","jugo de ½ limón","200 g de harina integral","1 cucharadita rasa de mezcla de especias dulces","40 g de pasas de Corinto","10 g de cáscaras de cítricos mixtas, picadas","1 cucharada de harina común para extender","1 cucharadita de azúcar extrafina"],
 ["Precaliente el horno a 170 °C (marca de gas 3).","En un tazón grande, bata el aceite, el huevo, el azúcar, la stevia, la ralladura de limón y el jugo de limón.","Agregue la harina, las especias, las pasas de Corinto y las cáscaras, y mezcle bien hasta que la mezcla forme una bola.","Coloque la masa sobre una superficie bien enharinada y extiéndala hasta que tenga un grosor de 3 a 4 mm.","Con un cortador de masa acanalado de 5 cm, corte las galletas y colóquelas con cuidado sobre una bandeja para hornear ligeramente engrasada, volviendo a extender los recortes de masa a medida que avanza. Debería obtener unas 25 galletas.","Hornee durante unos 7 a 9 minutos, hasta que apenas comiencen a dorarse en los bordes, espolvoree con el azúcar extrafina y deje enfriar sobre una rejilla."],
 ["Podría usar un cortador de galletas con forma, como de conejo o de pato, para hacer divertidas galletas de Pascua para los niños.","Si no tiene pasas de Corinto, las pasas o las pasas sultanas funcionan igual de bien, o use 50 g de fruta seca mixta en lugar de las pasas de Corinto y la cáscara mixta.","Instrucciones para congelar: Se pueden congelar una vez cocidas. Congélelas en porciones envueltas individualmente. Descongele durante 2 horas o en el microondas."],[]),
("بسكويت عيد الفصح","يرتبط هذا البسكويت غالبًا بمنطقة الغرب في إنجلترا (West Country)، وكان يُؤكل تقليديًا في أحد الفصح.","25","19 جم",
 ["6 ملاعق كبيرة من زيت الكانولا","1 بيضة","50 جم من السكر البني الطري (10 ملاعق صغيرة مكتنزة)","1.5-2 ملعقة صغيرة من الستيفيا أو مُحلٍّ آخر (يعادل 5 ملاعق صغيرة مكتنزة من السكر)","قشر 1 ليمونة مبشور ناعمًا","عصير ½ ليمونة","200 جم من دقيق القمح الكامل","1 ملعقة صغيرة مستوية من خليط التوابل الحلوة","40 جم من زبيب كورنثيا","10 جم من قشور الحمضيات المشكّلة المفرومة","1 ملعقة كبيرة من الدقيق العادي للفرد","1 ملعقة صغيرة من السكر الناعم"],
 ["سخّن الفرن مسبقًا إلى 170° مئوية (درجة الغاز 3).","في وعاء كبير، اخفق الزيت والبيضة والسكر والستيفيا وقشر الليمون وعصيره.","أضف الدقيق والتوابل وزبيب كورنثيا والقشور واخلط جيدًا حتى يتكوّن من الخليط كرة عجين.","اقلب العجين على سطح مرشوش جيدًا بالدقيق وافرده حتى يصبح سمكه 3-4 مم.","باستخدام قاطعة عجين مسننة قطرها 5 سم، قطّع البسكويت وضعه بحذر على صينية خبز مدهونة بقليل من الزيت، مع إعادة فرد بقايا العجين أولًا بأول. يجب أن تحصل على نحو 25 قطعة بسكويت.","اخبزه لمدة 7-9 دقائق تقريبًا حتى تبدأ حوافه بالاحمرار، ثم رشّ عليه السكر الناعم واتركه يبرد على رف سلكي."],
 ["يمكنك استخدام قاطعة بسكويت على شكل أرنب أو بطة مثلًا لتحضير بسكويت عيد الفصح ممتع للأطفال.","إذا لم يتوفر لديك زبيب كورنثيا، فإن الزبيب العادي أو الزبيب الأصفر يناسب الوصفة تمامًا، أو استخدم 50 جم من الفاكهة المجففة المشكّلة بدلًا من زبيب كورنثيا والقشور المشكّلة.","تعليمات التجميد: يمكن تجميده بعد الطهي. جمّده في حصص ملفوفة بشكل فردي. اتركه ليذوب لمدة ساعتين أو في الميكروويف."],[])))
R.append((7843879,
("Pollo piri piri","Pollo marinado con chile picante y pimentón para asar a la parrilla, a la plancha o en barbacoa. Sirva con un chorrito de jugo de limón verde.","2","220 g",
 ["2 pechugas de pollo sin piel (unos 350 g)","2 cucharaditas de aceite de oliva","1 a 2 chiles rojos, finamente picados","4 dientes de ajo, machacados","2 cucharaditas de pimentón","jugo de 1 limón verde","1 limón verde, para servir"],
 ["Corte las pechugas de pollo en 2 o 3 trozos, según el tamaño, para obtener rebanadas de 1 cm de grosor.","Coloque las rebanadas de pollo en una bolsa para alimentos y agregue el aceite de oliva, los chiles, el ajo, el pimentón y el jugo de limón verde. Mezcle bien para que el pollo quede cubierto. Deje reposar durante 15 minutos o refrigere y deje toda la noche.","Caliente el grill, la barbacoa o la plancha y agregue el pollo. Voltee después de 3 minutos y cocine otros 3 minutos. Verifique que esté bien cocido y que no quede carne rosada en el centro. Colóquelo en un plato.","Por último, corte el limón verde por la mitad y póngalo con el lado cortado hacia abajo sobre la plancha durante un par de minutos. Sirva con el pollo."],
 ["También podría usar esta marinada piri piri en filetes de pavo o de cerdo.","Para una versión vegetariana, cocine y deje enfriar trozos grandes de verduras como zanahorias, betabeles, camotes, papas o calabaza butternut, y márinelos en la mezcla piri piri antes de asarlos a la parrilla o en la barbacoa.","Para congelar, envuelva en papel aluminio o papel encerado dentro de bolsas para congelador y etiquete. Se conservan hasta por 3 meses.","@FV"],[]),
("دجاج بيري بيري","دجاج متبّل بالفلفل الحار والبابريكا للشواء على الشواية أو المقلاة المضلعة أو الفحم. قدّمه مع عصرة من عصير الليمون الأخضر.","2","220 جم",
 ["2 صدر دجاج بدون جلد (نحو 350 جم)","2 ملعقة صغيرة من زيت الزيتون","1-2 حبة فلفل حار أحمر، مفرومة ناعمًا","4 فصوص ثوم، مهروسة","2 ملعقة صغيرة من البابريكا","عصير 1 ليمونة خضراء","1 ليمونة خضراء، للتقديم"],
 ["قطّع صدور الدجاج إلى 2-3 قطع، بحسب حجمها، للحصول على شرائح بسمك 1 سم.","ضع شرائح الدجاج في كيس طعام وأضف زيت الزيتون والفلفل الحار والثوم والبابريكا وعصير الليمون الأخضر. اخلطها جيدًا حتى يتغطى الدجاج. اتركه جانبًا لمدة 15 دقيقة أو ضعه في الثلاجة واتركه طوال الليل.","سخّن الشواية أو الفحم أو المقلاة المضلعة وضع الدجاج. اقلبه بعد 3 دقائق واتركه ينضج 3 دقائق أخرى. تأكد من أنه ناضج تمامًا وأنه لا يوجد لحم وردي اللون في الوسط. ضعه في طبق.","وأخيرًا، اقطع الليمونة الخضراء إلى نصفين وضعها وجهها المقطوع إلى الأسفل على المقلاة المضلعة لبضع دقائق. قدّمها مع الدجاج."],
 ["يمكنك أيضًا استخدام تتبيلة البيري بيري هذه مع شرائح الديك الرومي أو لحم الخنزير.","للحصول على نسخة نباتية، اطهِ قطعًا كبيرة من الخضار مثل الجزر أو الشمندر أو البطاطا الحلوة أو البطاطس أو قرع الباترنت واتركها لتبرد، ثم تبّلها بخليط البيري بيري قبل شويها على الشواية أو الفحم.","للتجميد، لفّه بورق الألمنيوم/ورق الزبدة داخل أكياس التجميد وضع عليها ملصقًا. يمكن حفظه حتى 3 أشهر.","@FV"],[])))
R.append((7844829,
("Brochetas de cordero especiadas","Dé un toque especiado a su cena con estas deliciosas brochetas de cordero, donde la carne jugosa y las verduras crujientes se combinan para ofrecerle una cena verdaderamente espectacular. Esta receta fue seleccionada en colaboración con Slimming World.","4","621 g",
 ["750 g de papas harinosas, como King Edward o Maris Piper, cortadas en papas fritas gruesas","Aceite en aerosol para cocinar bajo en calorías","2 cucharaditas de comino molido","2 cucharaditas de pimentón ahumado dulce","2 cucharaditas de orégano seco","Ralladura y jugo de 1 limón sin encerar","2 bistecs gruesos (360 g) de pierna de cordero magro, sin grasa visible, cortados en trozos","2 cebollas moradas medianas, cortadas en gajos","2 pimientos grandes (de cualquier color), sin semillas y cortados en trozos","Rodajas de limón, para servir","Ensalada mixta grande, para servir","Unas cuantas hojas de menta fresca, para servir"],
 ["Precaliente el horno a 200 °C (180 °C con ventilador, marca de gas 6).","Mezcle el comino, el pimentón, el orégano, la ralladura y el jugo de limón en un plato hondo. Agregue el cordero, mézclelo para cubrirlo de manera uniforme, luego tape y refrigere durante al menos 1 hora, o toda la noche si es posible.","Ponga las papas en una cacerola con agua hirviendo a fuego alto y cocine durante 5 minutos. Escurra bien, regrese a la cacerola y tape. Deje enfriar un poco y luego agite la cacerola para que los bordes queden ásperos.","Forre una bandeja para hornear con papel para hornear antiadherente y acomode las papas en una sola capa. Espolvoree con pimienta negra recién molida y un poco de pimentón ahumado, rocíe con un par de pulverizaciones de aceite en aerosol bajo en calorías y hornee durante 25 minutos o hasta que estén doradas.","Precaliente el grill a temperatura medio-alta. Ensarte el cordero, las cebollas y los pimientos en 4 brochetas de metal y áselos de 10 a 12 minutos, volteándolos de vez en cuando, hasta que estén completamente cocidos. (También puede cocinarlos en una plancha antiadherente o en la barbacoa durante aproximadamente el mismo tiempo.)","Sirva caliente, con las rodajas de limón, la ensalada y las papas, y esparza la menta por encima."],
 ["Asegúrese de que el cordero esté cocido por completo y de seguir las prácticas de seguridad alimentaria.","@FV"],[]),
("أسياخ لحم الضأن المتبّلة","أضف نكهة التوابل إلى وجبة العشاء مع أسياخ لحم الضأن اللذيذة هذه، حيث يجتمع اللحم العصاري والخضار المقرمشة ليمنحوك عشاءً مميزًا حقًا. تم اختيار هذه الوصفة بالشراكة مع Slimming World.","4","621 جم",
 ["750 جم من البطاطس الدقيقية، مثل كينغ إدوارد أو ماريس بايبر، مقطعة إلى أصابع سميكة","بخاخ طهي قليل السعرات الحرارية","2 ملعقة صغيرة من الكمون المطحون","2 ملعقة صغيرة من البابريكا المدخّنة الحلوة","2 ملعقة صغيرة من الأوريجانو المجفف","قشر مبشور وعصير 1 ليمونة غير مشمّعة","2 شريحة سميكة (360 جم) من فخذ الضأن الخالي من الدهن، بعد إزالة الدهون الظاهرة، مقطعة قطعًا","2 حبة بصل أحمر متوسطة، مقطعة إلى أسافين","2 حبة فلفل رومي كبيرة (بأي لون)، منزوعة البذور ومقطعة قطعًا","شرائح ليمون للتقديم","سلطة مشكّلة كبيرة للتقديم","بضع أوراق نعناع طازجة للتقديم"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (180° مئوية مع المروحة، درجة الغاز 6).","اخلط الكمون والبابريكا والأوريجانو وقشر الليمون وعصيره في طبق مسطح. أضف لحم الضأن وقلّبه ليتغطى بالتساوي، ثم غطِّه وضعه في الثلاجة لمدة 1 ساعة على الأقل، أو طوال الليل إن أمكن.","ضع أصابع البطاطس في قدر من الماء المغلي على نار عالية واتركها 5 دقائق. صفِّها جيدًا وأعدها إلى القدر وضع الغطاء. اتركها لتبرد قليلًا، ثم هزّ القدر لتخشين الحواف.","بطّن صينية خبز بورق خبز غير لاصق ووزّع أصابع البطاطس عليه في طبقة واحدة. رشّ عليها فلفلًا أسود مطحونًا طازجًا وقليلًا من البابريكا المدخّنة، ثم رشّها بضغطتين من بخاخ الطهي قليل السعرات الحرارية واخبزها لمدة 25 دقيقة أو حتى تصبح ذهبية اللون.","سخّن الشواية مسبقًا على حرارة متوسطة إلى عالية. اغرس لحم الضأن والبصل والفلفل الرومي في 4 أسياخ معدنية واشوِها لمدة 10-12 دقيقة مع تقليبها من حين لآخر حتى تنضج تمامًا. (يمكنك أيضًا طهيها في مقلاة مضلعة غير لاصقة أو على الفحم لمدة مماثلة تقريبًا.)","قدّمها ساخنة مع شرائح الليمون والسلطة وأصابع البطاطس، وانثر النعناع فوقها."],
 ["تأكد من نضج لحم الضأن تمامًا ومن اتباع ممارسات سلامة الغذاء.","@FV"],[])))
R.append((7845092,
("Ensalada de pollo a la parrilla con aderezo de aguacate","Esta ensalada súper sabrosa es una excelente opción de almuerzo saludable.","2","402 g",
 ["2 pechugas de pollo (150 g cada una)","2 cucharadas de yogur griego","1 cucharada de yogur natural","2 cucharadas de jugo de limón","1 cucharada de tomillo fresco","100 g de rábano daikon (mooli) o rábano, en rodajas finas","10 cm de pepino, sin semillas y en rodajas","4 cebollines, en rodajas muy finas","75 g de brotes de frijol","1 caja de berro","½ aguacate","1 cucharada de vinagre de arroz","1 cucharada de aceite de ajonjolí","1 cucharada de cilantro picado","1 cucharada de semillas de ajonjolí tostadas"],
 ["Coloque las pechugas de pollo entre dos hojas de film plástico y golpéelas con un rodillo hasta que tengan 1 cm de grosor. Mezcle el yogur, el limón y el tomillo y sazone con pimienta.","Ponga el pollo y la marinada en un tazón y deje reposar durante 15 minutos.","Mientras tanto, ponga el rábano daikon, el pepino, los cebollines, los brotes de frijol y el berro en una ensaladera grande y mezcle.","Agregue el aguacate, el vinagre, el aceite, el cilantro y el yogur a una licuadora y licue hasta que quede suave. Cocine el pollo en la barbacoa, en una plancha de parrilla o bajo el grill durante unos 8 minutos, volteándolo una vez, hasta que esté bien cocido. Compruebe que no se vea carne rosada y que los jugos salgan claros al pinchar la parte más gruesa del pollo.","Rocíe el aderezo sobre la ensalada, esparza las semillas de ajonjolí, coloque encima el pollo rebanado y sirva."],
 ["@FV"],[]),
("سلطة الدجاج المشوي مع صلصة الأفوكادو","هذه السلطة اللذيذة جدًا خيار رائع لوجبة غداء صحية.","2","402 جم",
 ["2 صدر دجاج (150 جم لكل صدر)","2 ملعقة كبيرة من الزبادي اليوناني","1 ملعقة كبيرة من الزبادي الطبيعي","2 ملعقة كبيرة من عصير الليمون","1 ملعقة كبيرة من الزعتر الطازج","100 جم من الفجل الأبيض (موولي) أو الفجل الأحمر، مقطع إلى شرائح رفيعة","10 سم من الخيار، منزوع البذور ومقطع إلى شرائح","4 حبات بصل أخضر، مقطعة إلى شرائح رفيعة جدًا","75 جم من نبتات الفاصولياء","1 علبة من الجرجير المائي","½ حبة أفوكادو","1 ملعقة كبيرة من خل الأرز","1 ملعقة كبيرة من زيت السمسم","1 ملعقة كبيرة من الكزبرة الخضراء المفرومة","1 ملعقة كبيرة من بذور السمسم المحمصة"],
 ["ضع صدور الدجاج بين طبقتين من ورق التغليف البلاستيكي واطرقها بالشوبك حتى يصبح سمكها 1 سم. اخلط الزبادي والليمون والزعتر وتبّل بالفلفل.","ضع الدجاج والتتبيلة في وعاء واتركه لمدة 15 دقيقة.","في هذه الأثناء، ضع الفجل الأبيض والخيار والبصل ونبتات الفاصولياء والجرجير المائي في وعاء سلطة كبير وقلّبها.","ضع الأفوكادو والخل والزيت والكزبرة الخضراء والزبادي في الخلاط واخلطها حتى تصبح ناعمة. اطهِ الدجاج على الفحم أو في مقلاة مضلعة أو تحت الشواية لمدة 8 دقائق تقريبًا، مع تقليبه مرة واحدة حتى ينضج تمامًا. تأكد من عدم ظهور لحم وردي اللون ومن أن العصارة تخرج صافية عند وخز أسمك جزء من الدجاج.","رشّ الصلصة فوق السلطة وانثر بذور السمسم، وضع فوقها شرائح الدجاج وقدّمها."],
 ["@FV"],[])))
R.append((7848709,
("Panqueques (crepas)","Estos panqueques sin gluten son excelentes para servir con rellenos dulces o salados.","6","93 g",
 ["100 g de arroz molido","25 g de maicena","2 huevos, batidos","300 ml de leche semidescremada","un poco de aceite para freír"],
 ["Bata todos los ingredientes en un tazón.","Caliente una sartén antiadherente mediana y úntela con un poco de aceite.","Revuelva la masa antes de agregar un cucharón a la sartén; incline la sartén para que la mezcla cubra la base. Cocine de 1 a 2 minutos por cada lado, hasta que esté dorada.","Repita hasta terminar la mezcla (cada vez, revuelva la masa antes de ponerla en la sartén). Pase a un plato y sirva con fruta."],
 ["Para mantener los panqueques calientes, coloque un plato sobre una cacerola con agua a fuego lento y apile los panqueques encima a medida que los prepara.","Estos panqueques también quedan muy bien con rellenos salados. Pruebe con puerro y champiñones con una salsa de queso, o con ratatouille.","Instrucciones para congelar: Congele en porciones envueltas individualmente con papel encerado entre cada crepa. Descongele durante 1 hora o en el microondas.","@FV"],[]),
("فطائر البان كيك (الكريب)","هذه الفطائر الخالية من الغلوتين رائعة عند تقديمها مع الحشوات الحلوة أو المالحة.","6","93 جم",
 ["100 جم من الأرز المطحون","25 جم من نشا الذرة","2 بيضة، مخفوقة","300 مل من الحليب نصف منزوع الدسم","قليل من الزيت للقلي"],
 ["اخفق جميع المكونات معًا في وعاء.","سخّن مقلاة متوسطة غير لاصقة وادهنها بقليل من الزيت.","حرّك الخليط قبل إضافة مغرفة منه إلى المقلاة، وحرّك المقلاة بحيث يغطي الخليط قاعها. اطهِه لمدة 1-2 دقيقة على كل جانب حتى يصبح ذهبي اللون.","كرر العملية حتى ينتهي الخليط (حرّك الخليط في كل مرة قبل إضافته إلى المقلاة). اقلبها في طبق وقدّمها مع الفاكهة."],
 ["للحفاظ على دفء الفطائر، ضع طبقًا فوق قدر من الماء على نار هادئة وكدّس الفطائر فوقه أثناء تحضيرها.","هذه الفطائر لذيذة أيضًا مع الحشوات المالحة. جرّب الكراث والفطر مع صلصة الجبن، أو الراتاتوي.","تعليمات التجميد: جمّدها في حصص ملفوفة بشكل فردي مع وضع ورق زبدة بين كل فطيرة وأخرى. اتركها لتذوب لمدة 1 ساعة أو في الميكروويف.","@FV"],[])))
R.append((7854676,
("Hummus de betabel","Este vibrante hummus tiene menos grasa que las recetas tradicionales y es un platillo muy colorido para fiestas.","8","79 g",
 ["1 lata de 400 g de garbanzos, escurridos y enjuagados","1 paquete de 300 g de betabel cocido en su propio jugo o agua, escurrido","1 diente de ajo, machacado","una pizca de pimienta de cayena","1 cucharadita de comino","pimienta negra recién molida","2 cucharaditas de tahini","3 cucharadas de yogur natural","jugo de ½ limón","1 cucharadita de menta picada, para servir","crudités de verduras, para servir"],
 ["Licue la mitad de los garbanzos de la lata junto con todos los demás ingredientes hasta que quede casi suave y bien integrado.","Triture toscamente los garbanzos restantes con un tenedor e incorpórelos a la mezcla; esto le da textura al hummus. Espolvoree la menta y sirva con crudités de verduras."],
 ["La botana perfecta para fiestas: colóquelo en un tazón rodeado de bastones de zanahoria, pimiento, pepino y apio, y tiras de pan pita.","Sirva con pan pita caliente, además de verduras o ensalada, para una botana más sustanciosa.","@FV"],[]),
("حمص بالشمندر","هذا الحمص النابض بالألوان أقل دهونًا من الوصفات التقليدية، ويُعدّ طبقًا رائع الألوان للحفلات.","8","79 جم",
 ["1 علبة (400 جم) من الحمص، مصفّى ومغسول","1 عبوة (300 جم) من الشمندر المطبوخ في عصيره الطبيعي/الماء، مصفّى","1 فص ثوم، مهروس","رشة من فلفل كايين","1 ملعقة صغيرة من الكمون","فلفل أسود مطحون طازجًا","2 ملعقة صغيرة من الطحينة","3 ملاعق كبيرة من الزبادي الطبيعي","عصير ½ ليمونة","1 ملعقة صغيرة من النعناع المفروم للتقديم","خضار نيئة مقطعة للتقديم"],
 ["اخلط نصف علبة الحمص مع جميع المكونات الأخرى حتى يصبح الخليط ناعمًا تقريبًا ومتجانسًا.","اهرس الحمص المتبقي هرسًا خشنًا بالشوكة وقلّبه مع الخليط؛ فهذا يضفي قوامًا على الحمص. انثر النعناع فوقه وقدّمه مع الخضار النيئة المقطعة."],
 ["غموس مثالي للحفلات – ضعه في وعاء تحيط به أعواد الجزر والفلفل الرومي والخيار والكرفس وأصابع خبز البيتا.","قدّمه مع خبز البيتا الدافئ بالإضافة إلى الخضار/السلطة للحصول على وجبة خفيفة أكثر إشباعًا.","@FV"],[])))
R.append((7854824,
("Chile de verduras","Económico y fácil de preparar, este platillo versátil se puede servir con arroz o camotes al horno, envuelto con una ensalada, o convertirse en enchiladas, tacos o nachos.","8","195 g",
 ["2 cucharaditas de aceite de canola","2 a 3 cebollas, finamente picadas","1 pimiento rojo, finamente picado","150 g de zanahorias, finamente picadas","1 calabacín, finamente picado","100 g de champiñones, finamente picados","1 a 2 cucharaditas de chile en polvo (suave o picante, según su gusto)","1 cucharadita de comino molido","1 cucharadita de orégano","1 lata de 800 g de tomates picados","1 lata de 400 g de lentejas en agua sin sal","1 lata de 400 g de frijoles cannellini en agua sin sal","1 cucharada de salsa de tomate (kétchup)","cilantro, para decorar"],
 ["Caliente el aceite en una olla grande, agregue las cebollas y cocine de 5 a 8 minutos, hasta que empiecen a dorarse.","Agregue el pimiento rojo, las zanahorias, el calabacín y los champiñones, y cocine otros 10 minutos.","A continuación, agregue el chile en polvo, el comino, el orégano y los tomates. Mezcle bien y cocine otros 10 minutos, revolviendo con regularidad.","Agregue las lentejas y los frijoles con su agua y el kétchup. Mezcle bien y lleve a un hervor suave. Tape y cocine a fuego lento durante 30 minutos, revolviendo con regularidad."],
 ["Guarde en el refrigerador hasta por tres días o congele.","Tenga cuidado con el chile: siempre puede agregar más, ¡pero no puede quitarlo! Agregue un poco y deje tiempo para que el picante se infunda, pruebe y agregue más solo si es necesario. Si lo comparte con amigos, hágalo suave y sirva con salsa de chile u hojuelas de chile aparte, para que cada quien pueda hacerlo más picante si lo desea.","Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador o en el microondas y recaliente bien hasta que esté bien caliente por completo.","@FV"],[]),
("تشيلي الخضار","اقتصادي وسهل التحضير، ويمكن تقديم هذا الطبق المتعدد الاستخدامات مع الأرز أو البطاطا الحلوة المشوية، أو ملفوفًا مع السلطة، أو تحويله إلى إنشيلادا أو تاكو أو ناتشوز.","8","195 جم",
 ["2 ملعقة صغيرة من زيت الكانولا","2-3 حبات بصل، مفرومة ناعمًا","1 حبة فلفل رومي أحمر، مفرومة ناعمًا","150 جم من الجزر، مفروم ناعمًا","1 حبة كوسا، مفرومة ناعمًا","100 جم من الفطر، مفروم ناعمًا","1-2 ملعقة صغيرة من مسحوق الفلفل الحار (خفيف أو حار، حسب ذوقك)","1 ملعقة صغيرة من الكمون المطحون","1 ملعقة صغيرة من الأوريجانو","1 علبة (800 جم) من الطماطم المقطعة","1 علبة (400 جم) من العدس في ماء غير مملح","1 علبة (400 جم) من فاصولياء كانيليني في ماء غير مملح","1 ملعقة كبيرة من كاتشب الطماطم","كزبرة خضراء للتزيين"],
 ["سخّن الزيت في قدر كبير، وأضف البصل واطهه لمدة 5-8 دقائق حتى يبدأ بالاحمرار.","أضف الفلفل الرومي الأحمر والجزر والكوسا والفطر، واطهها 10 دقائق أخرى.","بعد ذلك، أضف مسحوق الفلفل الحار والكمون والأوريجانو والطماطم. اخلط جيدًا، ثم اطهه 10 دقائق أخرى مع التحريك بانتظام.","أضف العدس والفاصولياء مع مائها والكاتشب. اخلط جيدًا واتركه حتى يبدأ بالغليان الهادئ. ضع الغطاء واتركه على نار هادئة لمدة 30 دقيقة مع التحريك بانتظام."],
 ["احفظه في الثلاجة لمدة تصل إلى ثلاثة أيام أو جمّده.","احذر من الفلفل الحار – يمكنك دائمًا إضافة المزيد لكن لا يمكنك إخراجه! أضف قليلًا واترك وقتًا لتنتشر حرارته، ثم تذوّق وأضف المزيد عند الحاجة فقط. إذا كنت ستشاركه مع الأصدقاء، فاجعله خفيفًا وقدّمه مع صلصة الفلفل الحار أو رقائقه على الجانب، ليتمكن من يرغب من زيادة حدّته.","تعليمات التجميد: يمكن تجميده بعد الطهي. اتركه ليذوب في الثلاجة أو الميكروويف وأعد تسخينه جيدًا حتى يصبح ساخنًا تمامًا.","@FV"],[])))
R.append((7856586,
("Ensalada de zanahoria, comino y cilantro","Una ensalada sabrosa que combina muy bien con una rebanada de quiche o un trozo de pescado o pollo a la parrilla.","4","103 g",
 ["1 cucharadita colmada de semillas de comino","2 cucharaditas de jugo de limón","2 cucharaditas de aceite de oliva extra virgen","½ cebolla morada, en rodajas muy finas","una buena molida de pimienta negra fresca","2 a 3 zanahorias (300 g)","hojas de cilantro fresco, para servir"],
 ["Ponga las semillas de comino en la palma de la mano y tritúrelas y frótelas suavemente con el pulgar de la otra mano para liberar los sabores; luego páselas a un tazón.","Agregue el jugo de limón, el aceite de oliva, la cebolla y la pimienta. Mezcle y reserve.","Use un pelador de verduras para sacar tiras finas de las zanahorias.","Mezcle las zanahorias con el aderezo y sirva espolvoreadas con unas cuantas hojas de cilantro fresco."],
 ["Puede usar semillas de amapola, de ajonjolí o de alcaravea en lugar de las semillas de comino. O pruebe con otro aceite, como el de ajonjolí tostado o el de nuez.","Para una ensalada realmente colorida, busque zanahorias de variedades antiguas, que además de naranjas pueden ser moradas, blancas o amarillas.","@FV"],[]),
("سلطة الجزر بالكمون والكزبرة","سلطة لذيذة تُقدَّم بشكل رائع مع شريحة كيش أو قطعة سمك أو دجاج مشوي.","4","103 جم",
 ["1 ملعقة صغيرة مكتنزة من بذور الكمون","2 ملعقة صغيرة من عصير الليمون","2 ملعقة صغيرة من زيت الزيتون البكر الممتاز","½ حبة بصل أحمر، مقطعة إلى شرائح رفيعة جدًا","رشة وافرة من الفلفل الأسود الطازج المطحون","2-3 حبات جزر (300 جم)","أوراق كزبرة خضراء طازجة للتقديم"],
 ["ضع بذور الكمون في كف يدك واسحقها وافركها برفق بإبهام يدك الأخرى لإطلاق نكهتها، ثم ضعها في وعاء.","أضف عصير الليمون وزيت الزيتون والبصل والفلفل. اخلط وضع الوعاء جانبًا.","استخدم مقشرة الخضار لتقشير الجزر إلى شرائح رفيعة طويلة.","قلّب الجزر مع التتبيلة وقدّمه مزينًا ببضع أوراق كزبرة خضراء طازجة."],
 ["يمكنك استخدام بذور الخشخاش أو السمسم أو الكراوية بدلًا من بذور الكمون. أو جرّب استخدام زيت مختلف مثل زيت السمسم المحمص أو زيت الجوز.","للحصول على سلطة زاهية الألوان حقًا، ابحث عن الجزر من الأصناف التراثية الذي قد يكون، إلى جانب البرتقالي، أرجوانيًا أو أبيض أو أصفر.","@FV"],[])))
R.append((7857625,
("Tabulé","Esta ensalada de sabor fresco es excelente para comer en verano.","2","327 g",
 ["150 g de trigo bulgur","3 cucharadas de perejil fresco, picado","3 cucharadas de menta fresca, picada","125 g de tomates cherry, cortados en cuartos","½ pepino, finamente picado","1 manojo de cebollines, en rodajas finas","ralladura y jugo de ½ limón","2 cucharadas de aceite de oliva","pimienta negra recién molida"],
 ["Ponga el trigo bulgur en un tazón y cúbralo con agua hirviendo. Deje en remojo de 15 a 20 minutos o hasta que los granos estén tiernos y escurra el líquido restante.","Mezcle todos los demás ingredientes y revuélvalos con el trigo bulgur, sazone y sirva."],
 ["Use quinoa como alternativa sin gluten.","Puede agregarle muchas cosas distintas al tabulé. Pruebe con pimientos dulces, cebolla morada, zanahoria, hinojo o apio finamente picados. Use cebollín o cilantro y verduras asadas como calabaza butternut, calabacines y berenjenas. O agregue pasas, nueces, semillas o granada.","Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador o en el microondas para servir, o caliente en el microondas.","@FV"],[]),
("تبولة","هذه السلطة المنعشة رائعة لتناولها في الصيف.","2","327 جم",
 ["150 جم من البرغل","3 ملاعق كبيرة من البقدونس الطازج، مفروم","3 ملاعق كبيرة من النعناع الطازج، مفروم","125 جم من الطماطم الكرزية، مقطعة أرباعًا","½ حبة خيار، مفرومة ناعمًا","1 حزمة بصل أخضر، مقطعة إلى شرائح رفيعة","قشر وعصير ½ ليمونة","2 ملعقة كبيرة من زيت الزيتون","فلفل أسود مطحون طازجًا"],
 ["ضع البرغل في وعاء وغطِّه بالماء المغلي. اتركه منقوعًا لمدة 15-20 دقيقة أو حتى تصبح الحبوب طرية، ثم صفِّ أي سائل متبقٍ.","اخلط جميع المكونات المتبقية وقلّبها مع البرغل، وتبّل وقدّم."],
 ["استخدم الكينوا كبديل خالٍ من الغلوتين.","يمكنك إضافة الكثير من المكونات المختلفة إلى التبولة. جرّب الفلفل الحلو أو البصل الأحمر أو الجزر أو الشمر أو الكرفس مفرومًا ناعمًا. استخدم الثوم المعمر أو الكزبرة الخضراء والخضار المشوية مثل قرع الباترنت والكوسا والباذنجان. أو أضف الزبيب أو المكسرات أو البذور أو الرمان.","تعليمات التجميد: يمكن تجميدها بعد الطهي. اتركها لتذوب في الثلاجة أو الميكروويف للتقديم أو سخّنها في الميكروويف.","@FV"],[])))
R.append((7859144,
("Risotto de tomate y pimiento rojo","Un risotto sencillo de inspiración mediterránea.","2","390 g",
 ["1 cucharada de aceite de canola","1 cebolla pequeña, finamente picada","100 g de arroz para risotto","1 lata de 400 g de tomates ciruela, con su jugo y pulpa hechos puré","150 ml de caldo de verduras bajo en sal","1 cucharada de queso parmesano fresco, rallado","1 lata de 400 g de pimientos del piquillo, escurridos y con la pulpa en rebanadas","pimienta negra recién molida"],
 ["Caliente el aceite en una sartén antiadherente. Agregue la cebolla y fría de 2 a 3 minutos, hasta que se ablande.","Incorpore el arroz y cúbralo con el aceite. Vierta los tomates y el caldo, lleve a ebullición y cocine a fuego lento de 15 a 20 minutos, revolviendo continuamente, hasta que el arroz esté apenas tierno.","Incorpore los ingredientes restantes, sazone bien, caliente por completo y sirva."],
 ["Tenga a mano una tetera con agua hirviendo. Si el risotto empieza a pegarse, puede agregar un chorrito de agua. Siempre que use agua hirviendo, no detendrá la cocción del arroz al añadirla.","Revolver el risotto constantemente durante la cocción ayuda a que quede más cremoso.","Instrucciones para congelar: Se puede congelar una vez cocinado. Enfríe rápidamente. Descongele en el refrigerador y recaliente bien hasta que esté bien caliente por completo. Consuma de inmediato y deseche las sobras.","@FV"],[]),
("ريزوتو الطماطم والفلفل الأحمر","ريزوتو بسيط مستوحى من المطبخ المتوسطي.","2","390 جم",
 ["1 ملعقة كبيرة من زيت الكانولا","1 حبة بصل صغيرة، مفرومة ناعمًا","100 جم من أرز الريزوتو","1 علبة (400 جم) من الطماطم البرقوقية، بعصيرها ولبّها مهروسة","150 مل من مرق الخضار قليل الملح","1 ملعقة كبيرة من جبن البارميزان الطازج، مبشور","1 علبة (400 جم) من الفلفل الحلو (بيمنتو)، مصفّاة ولبّها مقطع إلى شرائح","فلفل أسود مطحون طازجًا"],
 ["سخّن الزيت في مقلاة غير لاصقة. أضف البصل وقلّبه لمدة 2-3 دقائق حتى يذبل.","أضف الأرز وقلّبه ليتغطى بالزيت. اسكب الطماطم والمرق، واتركه حتى يغلي ثم على نار هادئة لمدة 15-20 دقيقة مع التحريك باستمرار حتى ينضج الأرز بالكاد.","قلّب المكونات المتبقية، وتبّل جيدًا، وسخّنه تمامًا وقدّمه."],
 ["احتفظ بإبريق ماء مغلي في متناول يدك. إذا بدأ الريزوتو يلتصق، يمكنك إضافة رشة من الماء. طالما تستخدم ماءً مغليًا، فلن يوقف ذلك نضج الأرز عند إضافته.","تحريك الريزوتو باستمرار أثناء الطهي يساعد على جعله أكثر كريمية.","تعليمات التجميد: يمكن تجميده بعد الطهي. برّده بسرعة. اتركه ليذوب في الثلاجة وأعد تسخينه جيدًا حتى يصبح ساخنًا تمامًا. تناوله فورًا وتخلّص من أي بقايا.","@FV"],[])))
R.append((7859226,
("Paquete de pescado","Este platillo de pescado al vapor es una opción saludable para una cena rápida.","1","394 g",
 ["1 filete grueso de pescado blanco, sin piel (unos 125 g)","1 puerro pequeño, en rodajas finas","1 lata de 215 g de frijoles blancos (butter beans), escurridos y enjuagados","1 ramita de perejil, picada","1 cucharada de crème fraîche baja en grasa mezclada con 1 cucharada de caldo","pimienta negra recién molida"],
 ["Precaliente el horno a 200 °C (marca de gas 6).","Corte un cuadrado grande de papel aluminio de unos 25 cm x 25 cm.","Coloque el pescado, el puerro, los frijoles y el perejil en el centro del papel aluminio y vierta encima la mezcla de crème fraîche y caldo, sazone con la pimienta y luego doble y selle para formar un paquete.","Colóquelo en una bandeja para hornear y cocine durante 15 minutos, hasta que el pescado esté opaco y se desmenuce fácilmente con un tenedor. Abra el paquete y pase el contenido a un plato para servir. Sirva con una rodaja de limón."],
 ["Podría usar 1 cucharada de vino blanco o jugo de limón en lugar del caldo.","Pruebe a agregar otras verduras, como chícharos chinos o espárragos.","Cocinar los alimentos al vapor en un paquete significa el mínimo desorden y es un método de cocción saludable.","@FV"],[]),
("لفافة السمك","طبق السمك المطهو على البخار هذا خيار صحي لعشاء سريع.","1","394 جم",
 ["1 قطعة سميكة من فيليه السمك الأبيض، منزوعة الجلد (نحو 125 جم)","1 حبة كراث صغيرة، مقطعة إلى شرائح رفيعة","1 علبة (215 جم) من الفاصولياء البيضاء الكبيرة (بوتر بينز)، مصفّاة ومغسولة","غصن بقدونس، مفروم","1 ملعقة كبيرة من كريم فريش قليل الدسم ممزوجة بـ 1 ملعقة كبيرة من المرق","فلفل أسود مطحون طازجًا"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (درجة الغاز 6).","قصّ مربعًا كبيرًا من ورق الألمنيوم بقياس 25 سم × 25 سم تقريبًا.","ضع السمك والكراث والفاصولياء والبقدونس في وسط ورق الألمنيوم، واسكب فوقها خليط كريم فريش والمرق بالملعقة، وتبّل بالفلفل، ثم اطوِ الورق وأحكم إغلاقه لتكوين لفافة.","ضعها على صينية خبز واتركها تنضج لمدة 15 دقيقة حتى يصبح السمك معتمًا ويتفتت بسهولة بالشوكة. افتح اللفافة وانقلها إلى طبق التقديم. قدّمها مع شريحة ليمون."],
 ["يمكنك استخدام 1 ملعقة كبيرة من النبيذ الأبيض أو عصير الليمون بدلًا من المرق.","جرّب إضافة خضار أخرى، مثل البازلاء السكرية أو الهليون.","طهي الطعام على البخار داخل لفافة يعني الحد الأدنى من الفوضى وهو أسلوب طهي صحي.","@FV"],[])))
build(2,R)
